// AudioClipCompilerTests.cpp - deterministic cooker tests use only generated bytes.

#include "TestHarness.h"

#include "Editor/AssetCompilers/AudioClipCompiler.h"

#include <array>
#include <chrono>
#include <filesystem>
#include <fstream>

namespace TerraEngine::EditorTests
{
	namespace
	{
		void WriteU16(std::ofstream& output, std::uint16_t value) { output.put(static_cast<char>(value)); output.put(static_cast<char>(value >> 8U)); }
		void WriteU32(std::ofstream& output, std::uint32_t value) { for(std::uint32_t shift = 0U; shift < 32U; shift += 8U) output.put(static_cast<char>(value >> shift)); }
	}

	void RegisterAudioClipCompilerTests(TestRegistry& registry)
	{
		registry.Add("Editor.Audio.Compile.WavPublishesCheckedTef", [](TestContext& context) {
			const auto workspace = std::filesystem::temp_directory_path() / ("TerraAudioCook-" + std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));
			std::filesystem::create_directories(workspace);
			const auto source = workspace / "tone.wav";
			const auto cooked = workspace / "tone.teaudio";
			{
				std::ofstream output(source, std::ios::binary);
				output.write("RIFF", 4); WriteU32(output, 40U); output.write("WAVEfmt ", 8); WriteU32(output, 16U);
				WriteU16(output, 1U); WriteU16(output, 1U); WriteU32(output, 8000U); WriteU32(output, 16000U); WriteU16(output, 2U); WriteU16(output, 16U);
				output.write("data", 4); WriteU32(output, 4U); WriteU16(output, 0U); WriteU16(output, 0U);
			}
			const auto report = TerraEngine::AssetPipeline::CompileAudioClip({source, cooked, TerraEngine::UUID{7U}});
			context.Expect(report.Succeeded() && std::filesystem::is_regular_file(cooked)
				&& report.metadata.frameCount == 2U && report.metadata.sampleRate == 8000U,
				"A valid minimal WAV must stage, validate, and atomically publish TEAF output.");
			std::error_code ignored;
			std::filesystem::remove_all(workspace, ignored);
		});
	}
}
